import sqlite3

def setup(db):
    db.execute("CREATE TABLE scores (player TEXT, points INTEGER)")


def add_score(db, player, points):
    db.execute("INSERT INTO scores VALUES (?, ?)", (player, points))
    db.commit()


def leaderboard(db):
    return db.execute("SELECT player, SUM(points) AS total FROM scores GROUP BY player ORDER BY total DESC").fetchall()

