import sqlite3

db = sqlite3.connect(":memory:")
db.executescript("""
CREATE TABLE authors (id INTEGER PRIMARY KEY, name TEXT);
CREATE TABLE books (title TEXT, author_id INTEGER REFERENCES authors(id));
INSERT INTO authors VALUES (1, 'M. Okafor'), (2, 'L. Brandt');
INSERT INTO books VALUES ('Night Trains', 1), ('Ten Small Rivers', 2), ('The Quiet Garden', 1);
""")

def books_with_authors(db):
    return db.execute("SELECT books.title, authors.name FROM books JOIN authors ON authors.id = books.author_id ORDER BY books.title").fetchall()

